CREATE FUNCTION public.before_insert_merchant_comments() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  NEW.created_at = COALESCE(NEW.created_at, CURRENT_TIMESTAMP);
  RETURN NEW;
END;
$$;


--
-- Name: calculate_outstanding_balance(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.calculate_outstanding_balance() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
 NEW.outstanding_balance = NEW.book_checked_out_total_value
        - COALESCE(NEW.money_received, 0)
        - COALESCE(NEW.book_quantity_checked_in * 25, 0);
 RETURN NEW;
END;
$$;


--
-- Name: calculate_seller_earnings(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.calculate_seller_earnings() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    NEW.seller_earnings := (NEW.physical_book_cash + NEW.physical_book_digital + NEW.digital_book_credit) * (
        SELECT organization_earnings FROM organization WHERE id = NEW.organization_id
    );
    RETURN NEW;
END;
$$;


--
-- Name: create_coupon_on_new_task(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_coupon_on_new_task() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    new_coupon_id INTEGER;
BEGIN
    -- Check if the task is 'new create proof'
    IF LOWER(NEW.task) = 'new create proof' AND NOT NEW.is_auto_generated THEN
        -- Start a transaction
        BEGIN
            -- Insert a new row into the coupon table
            INSERT INTO coupon (merchant_id, offer, value, exclusions, expiration, additional_info, task_id, book_id, is_auto_generated)
            VALUES (NEW.merchant_id, NEW.coupon_details, NULL, NULL, NULL, NULL, NEW.id, NEW.book_id, true)
            RETURNING id INTO new_coupon_id;

            -- Update the merchant_tasks table with the new coupon_id
            UPDATE merchant_tasks SET coupon_id = new_coupon_id WHERE id = NEW.id;
            
        -- Commit the transaction
        END;
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: create_task_on_new_coupon(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_task_on_new_coupon() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    new_merchant_name VARCHAR(75);
BEGIN
    -- Fetch the merchant_name based on the merchant_id
    SELECT merchant_name INTO new_merchant_name FROM merchant WHERE id = NEW.merchant_id LIMIT 1;

	-- Check if the coupon is not auto-generated
    IF NOT NEW.is_auto_generated THEN
    -- Insert a new row into the merchant_tasks table
    INSERT INTO merchant_tasks (category, task, merchant_id, assign, due_date, description, task_status, coupon_details, coupon_id, book_id, is_auto_generated)
    VALUES ('Coupon', 'New create proof', NEW.merchant_id, NULL, NULL, NULL, 'New', NULL, NEW.id, NEW.book_id, true);
    
    -- Get the newly inserted task's id
    SELECT id INTO NEW.task_id FROM merchant_tasks WHERE coupon_id = NEW.id;

    -- Update the coupon table with the new task_id
    UPDATE coupon SET task_id = NEW.task_id WHERE id = NEW.id;
    
END IF;

    RETURN NEW;
END;
$$;


