-- Name: delete_user_coupons_on_coupon_delete(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.delete_user_coupons_on_coupon_delete() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    -- Delete from user_coupon where coupon_id matches the deleted coupon
    DELETE FROM user_coupon
    WHERE coupon_id = OLD.id;

    RETURN OLD;
END;
$$;


--
-- Name: insert_coupon_location(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.insert_coupon_location() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    loc_id INT;
BEGIN
    IF NEW.location_ids IS NOT NULL THEN
        FOR loc_id IN SELECT UNNEST(NEW.location_ids) LOOP
            INSERT INTO coupon_location (coupon_id, location_id)
            VALUES (NEW.id, loc_id);
        END LOOP;
    END IF;
    
    RETURN NULL;  -- Returning null since we don't need to modify the inserted row in coupon_location
END;
$$;


--
-- Name: insert_coupon_with_locations(integer, text, numeric, text, text, integer[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.insert_coupon_with_locations(p_merchant_id integer, p_offer text, p_value numeric, p_exclusions text, p_additional_info text, p_location_ids integer[]) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
    new_coupon_id INTEGER;
    location_id INTEGER;
BEGIN
    INSERT INTO coupon (merchant_id, offer, value, exclusions, additional_info)
    VALUES (p_merchant_id, p_offer, p_value, p_exclusions, p_additional_info)
    RETURNING id INTO new_coupon_id;

    FOREACH location_id IN ARRAY p_location_ids
    LOOP
        INSERT INTO coupon_location (coupon_id, location_id)
        VALUES (new_coupon_id, location_id);
    END LOOP;
END;
$$;


